draw:
var cx = W * 0.5, cy = H * 0.5;
var R3 = Math.min(W, H) * 0.42;   // outer surface of shell
var R2 = R3 * 0.76;               // inner surface of shell (cavity wall)
var q = p.qc, Qs = p.qshell;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// the metal of the shell
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.arc(cx, cy, R3, 0, 6.2832);
ctx.arc(cx, cy, R2, 0, 6.2832, true);
ctx.fill();

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(cx, cy, R3, 0, 6.2832); ctx.stroke();
ctx.beginPath(); ctx.arc(cx, cy, R2, 0, 6.2832); ctx.stroke();

// Gaussian surface drawn inside the metal
var Rg = (R2 + R3) * 0.5;
ctx.strokeStyle = C.accent;
ctx.setLineDash([4, 4]);
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(cx, cy, Rg, 0, 6.2832); ctx.stroke();
ctx.setLineDash([]);

// field lines in the cavity: radial, count set by q
var nIn = Math.max(0, Math.round(Math.abs(q) * 2));
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.2;
for (var i = 0; i < nIn; i++) {
  var a = i * 6.2832 / Math.max(1, nIn) + 0.15;
  var r0 = 10, r1 = R2 - 2;
  var sgn = q >= 0 ? 1 : -1;
  ctx.beginPath();
  ctx.moveTo(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0);
  ctx.lineTo(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1);
  ctx.stroke();
  var am = (r0 + r1) * 0.5 + sgn * 6;
  ctx.beginPath();
  ctx.moveTo(cx + Math.cos(a) * am, cy + Math.sin(a) * am);
  ctx.lineTo(cx + Math.cos(a) * (am - sgn * 7) - Math.sin(a) * 4, cy + Math.sin(a) * (am - sgn * 7) + Math.cos(a) * 4);
  ctx.lineTo(cx + Math.cos(a) * (am - sgn * 7) + Math.sin(a) * 4, cy + Math.sin(a) * (am - sgn * 7) - Math.cos(a) * 4);
  ctx.closePath();
  ctx.fillStyle = C.figure;
  ctx.fill();
}

// field lines outside, count set by net enclosed charge q + Qs
var qOut = q + Qs;
var nOut = Math.max(0, Math.round(Math.abs(qOut) * 2));
ctx.strokeStyle = C.figure;
for (var j = 0; j < nOut; j++) {
  var b = j * 6.2832 / Math.max(1, nOut) + 0.4;
  var s0 = R3 + 2, s1 = R3 + Math.min(W, H) * 0.12;
  ctx.beginPath();
  ctx.moveTo(cx + Math.cos(b) * s0, cy + Math.sin(b) * s0);
  ctx.lineTo(cx + Math.cos(b) * s1, cy + Math.sin(b) * s1);
  ctx.stroke();
}

// charges
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx, cy, 8, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText(q >= 0 ? "+" : "-", cx, cy + 4);

// surface charge marks
function marks(radius, amount, inward) {
  var n = Math.min(18, Math.max(0, Math.round(Math.abs(amount) * 1.6)));
  ctx.fillStyle = C.ink;
  for (var m = 0; m < n; m++) {
    var a2 = m * 6.2832 / Math.max(1, n) + 0.05;
    var rr = radius + (inward ? 9 : -9);
    ctx.fillText(amount >= 0 ? "+" : "-", cx + Math.cos(a2) * rr, cy + Math.sin(a2) * rr + 4);
  }
}
marks(R2, -q, false);
marks(R3, qOut, true);

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("cavity wall: " + (-q).toFixed(1) + " nC", 8, 16);
ctx.fillText("outer surface: " + qOut.toFixed(1) + " nC", 8, 32);
ctx.textAlign = "right";
ctx.fillStyle = C.accent;
ctx.fillText("Gaussian surface inside the metal encloses 0", W - 8, H - 8);

out.note = "inner wall " + (-q).toFixed(1) + " nC, outer surface " + qOut.toFixed(1) + " nC, field outside is that of " + qOut.toFixed(1) + " nC at the centre";

var eps0 = 8.85e-12;
var A = p.area * 1e-4;          // cm^2 -> m^2
var d = p.gap * 1e-3;           // mm -> m
var V = p.volts;
var Cf = eps0 * A / d;          // farads
var Q = Cf * V;                 // coulombs
var E = V / d;                  // V/m
var U = 0.5 * Cf * V * V;
var F = Q * Q / (2 * eps0 * A);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// geometry on screen
var halfW = W * (0.16 + 0.26 * (p.area / 400));
var midY = H * 0.46;
var pix = H * 0.30 * (p.gap / 4);
if (pix < 10) pix = 10;
var yTop = midY - pix / 2, yBot = midY + pix / 2;
var xL = W * 0.5 - halfW, xR = W * 0.5 + halfW;

// plates
ctx.fillStyle = C.figure;
ctx.fillRect(xL, yTop - 6, 2 * halfW, 6);
ctx.fillRect(xL, yBot, 2 * halfW, 6);

// field lines with drifting markers
var n = 9;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.2;
for (var i = 0; i < n; i++) {
  var x = xL + (2 * halfW) * (i + 0.5) / n;
  ctx.beginPath();
  ctx.moveTo(x, yTop + 1);
  ctx.lineTo(x, yBot - 1);
  ctx.stroke();
  var frac = ((t * 0.45 + i * 0.11) % 1);
  var y = yTop + 2 + frac * (pix - 4);
  ctx.fillStyle = C.accent;
  ctx.beginPath();
  ctx.moveTo(x, y + 4);
  ctx.lineTo(x - 3.5, y - 3);
  ctx.lineTo(x + 3.5, y - 3);
  ctx.closePath();
  ctx.fill();
}

// charge signs
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
for (var k = 0; k < n; k++) {
  var xs = xL + (2 * halfW) * (k + 0.5) / n;
  ctx.fillText("+", xs, yTop - 10);
  ctx.fillText("-", xs, yBot + 20);
}

// gap arrow and label
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(xR + 16, yTop); ctx.lineTo(xR + 16, yBot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xR + 12, yTop + 5); ctx.lineTo(xR + 16, yTop); ctx.lineTo(xR + 20, yTop + 5); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xR + 12, yBot - 5); ctx.lineTo(xR + 16, yBot); ctx.lineTo(xR + 20, yBot - 5); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("d = " + p.gap.toFixed(2) + " mm", xR + 24, midY + 4);

// attraction arrows on the plates
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(xL - 14, yTop - 22); ctx.lineTo(xL - 14, yTop - 6); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xL - 18, yTop - 12); ctx.lineTo(xL - 14, yTop - 4); ctx.lineTo(xL - 10, yTop - 12); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xL - 14, yBot + 28); ctx.lineTo(xL - 14, yBot + 12); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xL - 18, yBot + 18); ctx.lineTo(xL - 14, yBot + 10); ctx.lineTo(xL - 10, yBot + 18); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.textAlign = "right";
ctx.fillText("pull", xL - 24, midY + 4);

// labels
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("E = V/d = " + (E / 1000).toFixed(1) + " kV/m", 8, 16);
ctx.fillText("A = " + p.area.toFixed(0) + " cm2, V = " + V.toFixed(0) + " V", 8, H - 8);

out.note = "C = " + (Cf * 1e12).toFixed(1) + " pF, Q = " + (Q * 1e9).toFixed(2) + " nC, U = " + (U * 1e9).toFixed(2) + " nJ, pull = " + (F * 1e6).toFixed(2) + " uN";

var k = 8.99e9;
var q = 3e-9;                 // fixed 3 nC
var h = p.height;             // cm
var plateY = H * 0.74;
var scale = (plateY - H * 0.10) / 6;   // pixels per cm, 6 cm fits
var cx = W * 0.5;
var cy = plateY - h * scale;
var iy = plateY + h * scale;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// field lines traced from the charge in the real half-space
var N = 16;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.1;
for (var i = 0; i < N; i++) {
  var a = -Math.PI * 0.5 + (i + 0.5) * (2 * Math.PI / N);
  var x = cx + Math.cos(a) * 9;
  var y = cy + Math.sin(a) * 9;
  ctx.beginPath();
  ctx.moveTo(x, y);
  for (var s = 0; s < 500; s++) {
    var dx1 = x - cx, dy1 = y - cy;
    var r1 = Math.sqrt(dx1 * dx1 + dy1 * dy1); if (r1 < 1) r1 = 1;
    var dx2 = x - cx, dy2 = y - iy;
    var r2 = Math.sqrt(dx2 * dx2 + dy2 * dy2); if (r2 < 1) r2 = 1;
    var ex = dx1 / (r1 * r1 * r1) - dx2 / (r2 * r2 * r2);
    var ey = dy1 / (r1 * r1 * r1) - dy2 / (r2 * r2 * r2);
    var m = Math.sqrt(ex * ex + ey * ey); if (m === 0) break;
    x += 2.2 * ex / m;
    y += 2.2 * ey / m;
    if (y >= plateY || x < 0 || x > W || y < 0) break;
    ctx.lineTo(x, y);
  }
  ctx.stroke();
}

// the plate
ctx.fillStyle = C.faint;
ctx.fillRect(0, plateY, W, H * 0.10);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(0, plateY); ctx.lineTo(W, plateY); ctx.stroke();

// induced surface charge density, sigma(x) proportional to -h/(x^2+h^2)^1.5
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.beginPath();
var peak = 1 / (h * h);
for (var xi = 0; xi <= W; xi += 3) {
  var xm = (xi - cx) / scale;
  var val = h / Math.pow(xm * xm + h * h, 1.5);
  var yy = plateY + (val / peak) * (H * 0.09);
  if (xi === 0) ctx.moveTo(xi, yy); else ctx.lineTo(xi, yy);
}
ctx.stroke();

// the real charge
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx, cy, 8, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.paper;
ctx.textAlign = "center";
ctx.fillText("+", cx, cy + 4);

// the image charge, ghosted
ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 3]);
ctx.lineWidth = 1.2;
ctx.beginPath(); ctx.arc(cx, iy, 8, 0, 6.2832); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx, cy + 9); ctx.lineTo(cx, iy - 9); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.fillText("-", cx, iy + 4);

// labels
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("+q at h", cx + 14, cy + 4);
ctx.fillText("image -q at -h (not real)", cx + 14, iy + 4);
ctx.fillText("grounded conductor, V = 0", 8, plateY + H * 0.10 - 6);
ctx.fillStyle = C.accent;
ctx.fillText("induced surface charge", 8, 16);

var F = k * q * q / (4 * h * h * 1e-4);
var Wk = k * q * q / (4 * h * 1e-2);
out.note = "h = " + h.toFixed(1) + " cm, attraction F = " + (F * 1e9).toFixed(2) + " nN, work to remove it to infinity = " + (Wk * 1e9).toFixed(3) + " nJ";
